insert into public.confissoes_documentos (id, titulo, sigla, ano, descricao, ordem_ciclo, fonte_url) values ($t$breve-catecismo$t$, $t$Breve Catecismo de Westminster$t$, $t$BCW$t$, $t$1647$t$, $t$Resumo da fé em 107 perguntas e respostas, preparado pela Assembleia de Westminster para a instrução dos crentes.$t$, $t$1$t$, $t$https://www.monergismo.com/textos/catecismos/brevecatecismo_westminster.htm$t$);
