insert into public.confissoes_itens (id, documento_id, ordem, secao, rotulo, pergunta, texto, referencias) values
  ($t$breve-catecismo-1$t$, $t$breve-catecismo$t$, 1, null, $t$Pergunta 1$t$, $t$Qual é o fim principal do homem?$t$, $t$O fim principal do homem é glorificar a Deus, e gozá-lo para sempre.$t$, $t$Rm 11.36; 1Co 10.31; Sl 73.25-26; Is 43.7; Rm 14.7-8; Ef 1.5-6; Is 60.21; 61.3.$t$),
  ($t$breve-catecismo-2$t$, $t$breve-catecismo$t$, 2, null, $t$Pergunta 2$t$, $t$Que regra deu Deus para nos dirigir na maneira de o glorificar e gozar?$t$, $t$A Palavra de Deus, que se acha nas Escrituras do Velho e do Novo Testamentos, é a única regra para nos dirigir na maneira de o glorificar e gozar.$t$, $t$Lc 24.27, 44; 2Pe 3.2, 15-16; 2Tm 3.15-17; Lc 16.29-31; Gl 1.8-9; Jo 15.10-11; Is 8.20; Hb 1:1 comparado com Lc 1.1-4 e Jo 20.30-31.$t$),
  ($t$breve-catecismo-3$t$, $t$breve-catecismo$t$, 3, null, $t$Pergunta 3$t$, $t$Qual é a coisa principal que as Escrituras nos ensinam?$t$, $t$A coisa principal que as Escrituras nos ensinam é o que o homem deve crer acerca de Deus, o dever que Deus requer do homem.$t$, $t$Jo 5.39; 20.31; Sl 119.105; Rm 15.4; 1Co 10.11.$t$),
  ($t$breve-catecismo-4$t$, $t$breve-catecismo$t$, 4, null, $t$Pergunta 4$t$, $t$Quem é Deus?$t$, $t$Deus é espírito, infinito, eterno e imutável em seu ser, sabedoria, poder, santidade, justiça, bondade e verdade.$t$, $t$Jo 4.24; Ex 3.14; Sl 145.3; 90.2; Tg 1.17; Rm 11.33; Gn 17.1, Ap 4.8; Ex 34.6-7.$t$),
  ($t$breve-catecismo-5$t$, $t$breve-catecismo$t$, 5, null, $t$Pergunta 5$t$, $t$Há mais de um Deus?$t$, $t$Há só um Deus, o Deus vivo e verdadeiro.$t$, $t$Dt 6.4; 1Co 8.4; Jr 10.10; Jo 17.3.$t$),
  ($t$breve-catecismo-6$t$, $t$breve-catecismo$t$, 6, null, $t$Pergunta 6$t$, $t$Quantas pessoas há na Divindade?$t$, $t$Há três pessoas na Divindade: o Pai, o Filho e o Espírito Santo, e estas três são um Deus, da mesma substância, iguais em poder e glória.$t$, $t$Mt 3.16-17; 28.19; 2Co 13.13; Jo 1.1; 3.18; At 5.3-4; Hb 1.3; Jo 10.30.$t$),
  ($t$breve-catecismo-7$t$, $t$breve-catecismo$t$, 7, null, $t$Pergunta 7$t$, $t$Que são os decretos de Deus?$t$, $t$Os decretos de Deus são o seu eterno propósito, segundo o conselho da sua vontade, pelo qual, para sua própria glória, Ele predestinou tudo o que acontece.$t$, $t$Rm 11.36; Ef 1.4-6, 11; At 2.23; 17.26; Jo 21.19; Is 44.28; At 13.48; 1Co 2.7; Ef 3.10-11.$t$),
  ($t$breve-catecismo-8$t$, $t$breve-catecismo$t$, 8, null, $t$Pergunta 8$t$, $t$Como executa Deus os seus decretos?$t$, $t$Deus executa os seus decretos nas obras da criação e da providência.$t$, $t$Ap 4.11; Dn 4.35; Is 40.26; 14.26-27; 46.9-11; At 4.24.$t$),
  ($t$breve-catecismo-9$t$, $t$breve-catecismo$t$, 9, null, $t$Pergunta 9$t$, $t$Qual é a obra da criação?$t$, $t$A obra da criação é aquela pela qual, Deus fez todas as coisas do nada, no espaço de seis dias, e tudo muito bem.$t$, $t$Gn 1; Hb 11.3; Sl 33.9; Gn 1.31.$t$),
  ($t$breve-catecismo-10$t$, $t$breve-catecismo$t$, 10, null, $t$Pergunta 10$t$, $t$Como criou Deus o homem?$t$, $t$Deus criou o homem macho e fêmea, conforme a sua própria imagem, em conhecimento, retidão e santidade com domínio sobre as criaturas.$t$, $t$Gn 1.27-28; Cl 3.10; Ef 4.24; Rm 2.14-15; Sl 86-8.$t$),
  ($t$breve-catecismo-11$t$, $t$breve-catecismo$t$, 11, null, $t$Pergunta 11$t$, $t$Quais são as obras da providência de Deus?$t$, $t$As obras da providência de Deus são a sua maneira muito santa, sábia e poderosa de preservar e governar todas as suas criaturas, e todas as ações delas.$t$, $t$Sl 145.17; 104.10-24; Hb 1.3; Mt 10.29-30; Os 2.6.$t$),
  ($t$breve-catecismo-12$t$, $t$breve-catecismo$t$, 12, null, $t$Pergunta 12$t$, $t$Que ato especial de providência exerceu Deus para com o homem no estado em que ele foi criado?$t$, $t$Quando Deus criou o homem, fez com ele um pacto de vida, com a condição de perfeita obediência: proibindo-lhe comer da árvore da ciência do bem e do mal, sob pena de morte.$t$, $t$Gl 3.12; Gn 2.17.$t$),
  ($t$breve-catecismo-13$t$, $t$breve-catecismo$t$, 13, null, $t$Pergunta 13$t$, $t$Conservaram-se nossos primeiros pais no estado em que foram criados?$t$, $t$Nossos primeiros pais, sendo deixados à liberdade da sua própria vontade, caíram do estado em que foram criados, pecando contra Deus.$t$, $t$Rm 5.12; Gn 3.6.$t$),
  ($t$breve-catecismo-14$t$, $t$breve-catecismo$t$, 14, null, $t$Pergunta 14$t$, $t$Que é pecado?$t$, $t$Pecado é qualquer falta de conformidade com a lei de Deus, ou qualquer transgressão desta lei.$t$, $t$Tg 2.10; 4.17; 1Jo 3.4.$t$),
  ($t$breve-catecismo-15$t$, $t$breve-catecismo$t$, 15, null, $t$Pergunta 15$t$, $t$Qual foi o pecado pelo qual nossos primeiros pais caíram do estado em que foram criados?$t$, $t$O pecado pelo qual nossos primeiros pais caíram do estado em que foram criados foi o comerem do fruto proibido.$t$, $t$Gn 3.12-13; Os 6.7.$t$),
  ($t$breve-catecismo-16$t$, $t$breve-catecismo$t$, 16, null, $t$Pergunta 16$t$, $t$Caiu todo o gênero humano pela primeira transgressão de Adão?$t$, $t$Visto que o pacto foi feito com Adão não só para ele, mas também para sua posteridade, todo gênero humano que dele procede por geração ordinária, pecou nele e caiu com ele na sua primeira transgressão.$t$, $t$Gn 1.28; At 17.26; 1Co 15.21-22; Rm 5.12-14.$t$),
  ($t$breve-catecismo-17$t$, $t$breve-catecismo$t$, 17, null, $t$Pergunta 17$t$, $t$Qual foi o estado a que a queda reduziu o gênero humano?$t$, $t$A queda reduziu o gênero humano a um estado de pecado e miséria.$t$, $t$Rm 5.12.$t$),
  ($t$breve-catecismo-18$t$, $t$breve-catecismo$t$, 18, null, $t$Pergunta 18$t$, $t$Em que consiste o estado de pecado em que o homem caiu?$t$, $t$O estado de pecado em que o homem caiu consiste na culpa do primeiro pecado de Adão, na falta de retidão original e na corrupção de toda a sua natureza, o que ordinariamente de chama Pecado Original, juntamente com todas as transgressões atuais que procedem dele.$t$, $t$Rm 5.18-19; Ef 2.1-3; Rm 8.7-8; Sl 51.5.$t$),
  ($t$breve-catecismo-19$t$, $t$breve-catecismo$t$, 19, null, $t$Pergunta 19$t$, $t$Qual é a miséria do estado em que o homem caiu?$t$, $t$Todo o gênero humano pela sua queda perdeu comunhão com Deus, está debaixo da sua ira e maldição, e assim sujeito a todas as misérias nesta vida, à morte e às penas do Inferno para sempre.$t$, $t$Gn 3.8, 24; Ef 2.3; Rm 6.23; Mt 25.41-46.$t$),
  ($t$breve-catecismo-20$t$, $t$breve-catecismo$t$, 20, null, $t$Pergunta 20$t$, $t$Deixou Deus todo o gênero humano perecer no estado de pecado e miséria?$t$, $t$Tendo Deus, unicamente pela sua boa vontade desde toda a eternidade, escolhido alguns para a vida eterna, entrou com eles em um pacto de graça, para os livrar do estado de pecado e miséria, e trazer a um estado de salvação por meio de um Redentor.$t$, $t$Ef 1.4; Tt 1.2; 3.4-7; Jo 17.6.$t$),
  ($t$breve-catecismo-21$t$, $t$breve-catecismo$t$, 21, null, $t$Pergunta 21$t$, $t$Quem é o Redentor dos escolhidos de Deus?$t$, $t$O único redentor dos escolhidos de Deus é o Senhor Jesus Cristo que, sendo o eterno Filho de Deus, se fez homem, e assim foi e continua a ser Deus e homem em duas naturezas distintas, e uma só pessoa, para sempre.$t$, $t$1Tm 2.5; Jo 1.14; Rm 9.5; Cl 2.9; Hb 13.8.$t$),
  ($t$breve-catecismo-22$t$, $t$breve-catecismo$t$, 22, null, $t$Pergunta 22$t$, $t$Como Cristo, sendo o Filho de Deus, se fez homem?$t$, $t$Cristo, o Filho de Deus, fez-se homem tomando um verdadeiro corpo, e uma alma racional, sendo concebido pelo poder do Espirito Santo no ventre da virgem Maria, e nascido dela, mas sem pecado.$t$, $t$Hb 2.14; Mt 26.38; Lc 2.52; 1.31, 35; Hb 4.15.$t$),
  ($t$breve-catecismo-23$t$, $t$breve-catecismo$t$, 23, null, $t$Pergunta 23$t$, $t$Que funções exerce Cristo como nosso Redentor?$t$, $t$Cristo, como nosso Redentor, exerce as funções de profeta, sacerdote e rei, tanto no seu estado de humilhação como no de exaltação.$t$, $t$At 3.22; Hb 5.5-6; Sl 2.6; Jo 1.49.$t$),
  ($t$breve-catecismo-24$t$, $t$breve-catecismo$t$, 24, null, $t$Pergunta 24$t$, $t$Como exerce Cristo as funções de profeta?$t$, $t$Cristo exerce as funções de profeta, revelando-nos, pela sua Palavra e pelo seu Espírito, a vontade de Deus para a nossa salvação.$t$, $t$Jo 1.18; Hb 1.1-2; Jo 14.26; 16.13.$t$),
  ($t$breve-catecismo-25$t$, $t$breve-catecismo$t$, 25, null, $t$Pergunta 25$t$, $t$Como exerce Cristo as funções de sacerdote?$t$, $t$Cristo exerce as funções de sacerdote, oferecendo-se a si mesmo uma vez em sacrifício, para satisfazer a justiça divina, reconciliar-nos com Deus e fazendo contínua intercessão por nós.$t$, $t$Hb 9.28; Rm 3.24-26; 10.4; Hb 2.17; 7.25; Is 53.12.$t$),
  ($t$breve-catecismo-26$t$, $t$breve-catecismo$t$, 26, null, $t$Pergunta 26$t$, $t$Como exerce Cristo as funções de rei?$t$, $t$Cristo exerce as funções de rei, sujeitando-nos a si mesmo, governando-nos e protegendo-nos, contendo e subjugando todos os seus e os nossos inimigos.$t$, $t$Sl 110.3; At 2.36; 18.9-10; Is 9.6-7; 1Co 15.26-27.$t$),
  ($t$breve-catecismo-27$t$, $t$breve-catecismo$t$, 27, null, $t$Pergunta 27$t$, $t$Em que consistiu a humilhação de Cristo?$t$, $t$A humilhação de Cristo consistiu em Ele nascer, e isso em condição baixa, feito sujeito à lei; em sofrer as misérias desta vida, a ira de Deus e amaldiçoada morte na cruz; em ser sepultado, e permanecer debaixo do poder da morte durante certo tempo.$t$, $t$Lc 2.7; Fp 2.6-8; Gl 4.4; 3.13; Is 53.3; Mt 27.43; 1Co 15.3-4.$t$),
  ($t$breve-catecismo-28$t$, $t$breve-catecismo$t$, 28, null, $t$Pergunta 28$t$, $t$Em que consiste a exaltação de Cristo?$t$, $t$A exaltação de Cristo consiste em Ele ressurgir dos mortos no terceiro dia; em subir ao Céu e estar sentado à mão direita de Deus Pai, e em vir para julgar o mundo no último dia.$t$, $t$1Co 15.4; Ef 1.20-21; At 17.31.$t$),
  ($t$breve-catecismo-29$t$, $t$breve-catecismo$t$, 29, null, $t$Pergunta 29$t$, $t$Como nos tornamos participantes da redenção adquirida por Cristo?$t$, $t$Tornamo-nos participantes da redenção adquirida por Cristo pela eficaz aplicação dela a nós pelo Seu Santo Espírito.$t$, $t$Jo 1.12; 3.5-6; Tt 3.5-6.$t$),
  ($t$breve-catecismo-30$t$, $t$breve-catecismo$t$, 30, null, $t$Pergunta 30$t$, $t$Como nos aplica o Espírito a redenção adquirida por Cristo?$t$, $t$O Espírito aplica-nos a redenção adquirida por Cristo, operando em nós a fé, e unindo-nos a Cristo por meio dela em nossa vocação eficaz.$t$, $t$Gl 2.20; Ef 2.8; 1Co 12.12-13.$t$),
  ($t$breve-catecismo-31$t$, $t$breve-catecismo$t$, 31, null, $t$Pergunta 31$t$, $t$Que é vocação eficaz?$t$, $t$Vocação eficaz é a obra do Espírito Santo, pela qual, convencendo-nos do nosso pecado, e da nossa miséria, iluminando nossos entendimentos pelo conhecimento de Cristo, e renovando a nossa vontade, nos persuade e habilita a abraçar Jesus Cristo, que nos é oferecido de graça no Evangelho.$t$, $t$1Ts 2.13; At 2.37; 26.18; Ez 36.25-27; 2Tm 1.9; Fp 2.13; Jo 6.37, 44-45.$t$),
  ($t$breve-catecismo-32$t$, $t$breve-catecismo$t$, 32, null, $t$Pergunta 32$t$, $t$Que bênçãos gozam nesta vida aqueles que são eficazmente chamados?$t$, $t$Aqueles que são eficazmente chamados, gozam, nesta vida, da justificação, adoção e santificação, e das diversas bênçãos que acompanham estas graças ou delas procedem.$t$, $t$Rm 8.30; Ef 1.5; 1Co 1.30.$t$),
  ($t$breve-catecismo-33$t$, $t$breve-catecismo$t$, 33, null, $t$Pergunta 33$t$, $t$Que é justificação?$t$, $t$Justificação é um ato da livre graça de Deus, no qual Ele perdoa todos os nossos pecados, e nos aceita como justos diante de Si, somente por causa da justiça de Cristo a nós imputada, e recebida só pela fé.$t$, $t$Ef 1.7; 2Co 5.21; Rm 4.6; 5.18; Gl 2.16.$t$),
  ($t$breve-catecismo-34$t$, $t$breve-catecismo$t$, 34, null, $t$Pergunta 34$t$, $t$Que é adoção?$t$, $t$Adoção é um ato de livre graça de Deus, pelo qual somos recebidos no número dos filhos de Deus, e temos direito a todos os seus privilégios.$t$, $t$1Jo 3.1; Jo 1.12; Rm 8.14-17.$t$),
  ($t$breve-catecismo-35$t$, $t$breve-catecismo$t$, 35, null, $t$Pergunta 35$t$, $t$Que é santificação?$t$, $t$É a obra da livre graça de Deus, pela qual somos renovados em todo o nosso ser, segundo a imagem de Deus, e habilitados a morrer cada vez mais para o pecado e a viver para a retidão.$t$, $t$1Pe 1.2; Ef 4.20-24; Rm 6.6; 12.1-2.$t$),
  ($t$breve-catecismo-36$t$, $t$breve-catecismo$t$, 36, null, $t$Pergunta 36$t$, $t$Quais são as bênçãos que nesta vida acompanham a justificação, adoção e santificação ou delas procedem?$t$, $t$As bênçãos que nesta vida acompanham a justificação, adoção e santificação, ou delas procedem, são: certeza do amor de Deus, paz de consciência, gozo no Espírito Santo, aumento de graça, e perseverança nela até ao fim.$t$, $t$Rm 5.1-5; 14.17; Jo 1.16; Fp 1.6; 1Pe 1.5.$t$),
  ($t$breve-catecismo-37$t$, $t$breve-catecismo$t$, 37, null, $t$Pergunta 37$t$, $t$Quais são as bênçãos que os fiéis recebem de Cristo na hora da morte?$t$, $t$As almas dos fiéis na hora da morte são aperfeiçoadas em santidade, e imediatamente entram na glória; e os corpos que continuam unidos Cristo, descansam na sepultura até a ressurreição.$t$, $t$Ap 14.13; Lc 23.43; At 7.55, 59; Fp 1.23; 1Ts 4.14; Jo 5.28-29; 14.2-3; Hb 12.22-23.$t$),
  ($t$breve-catecismo-38$t$, $t$breve-catecismo$t$, 38, null, $t$Pergunta 38$t$, $t$Quais são as bênçãos que os fieis recebem de Cristo na ressurreição?$t$, $t$Na ressurreição, os fieis, sendo ressuscitados em glória, serão publicamente reconhecidos e absolvidos no dia de juízo, e tornados perfeitamente felizes no pleno gozo de Deus por toda a eternidade.$t$, $t$1Co 15.43; Mt 10.32; 25.34; Sl 16.11.$t$),
  ($t$breve-catecismo-39$t$, $t$breve-catecismo$t$, 39, null, $t$Pergunta 39$t$, $t$Qual é o dever que Deus exige do homem?$t$, $t$O dever que Deus exige do homem é obediência à sua vontade revelada.$t$, $t$Mq 6.8; Lc 10.27-28; Gn 17.1.$t$),
  ($t$breve-catecismo-40$t$, $t$breve-catecismo$t$, 40, null, $t$Pergunta 40$t$, $t$Que revelou Deus primeiramente ao homem para regra de sua obediência?$t$, $t$A regra que Deus revelou primeiramente ao homem para sua obediência foi a lei moral.$t$, $t$Rm 2.14-15.$t$),
  ($t$breve-catecismo-41$t$, $t$breve-catecismo$t$, 41, null, $t$Pergunta 41$t$, $t$Onde está a lei moral resumidamente compreendida?$t$, $t$A lei moral está resumidamente compreendida nos dez mandamentos.$t$, $t$Dt 10.4; Mt 19.17-19.$t$),
  ($t$breve-catecismo-42$t$, $t$breve-catecismo$t$, 42, null, $t$Pergunta 42$t$, $t$Em que se resumem os dez mandamentos?$t$, $t$Os dez mandamentos se resumem em amar ao Senhor nosso Deus de todo o nosso coração, de toda a nossa alma, de todas as nossas forças e de todo o nosso entendimento; e ao nosso próximo como a nós mesmos.$t$, $t$Mt 22-37-40.$t$),
  ($t$breve-catecismo-43$t$, $t$breve-catecismo$t$, 43, null, $t$Pergunta 43$t$, $t$Qual é o prefácio dos dez mandamentos?$t$, $t$O prefácio dos dez mandamentos é: "Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão".$t$, $t$Ex 20.2.$t$),
  ($t$breve-catecismo-44$t$, $t$breve-catecismo$t$, 44, null, $t$Pergunta 44$t$, $t$Que nos ensina o prefácio dos dez mandamentos?$t$, $t$O prefácio dos dez mandamentos ensina-nos que nós temos obrigação de guardar todos os mandamentos de Deus, por ser Ele o Senhor nosso Deus e Redentor.$t$, $t$Dt 11.1; 1Pe 1.15-19.$t$),
  ($t$breve-catecismo-45$t$, $t$breve-catecismo$t$, 45, null, $t$Pergunta 45$t$, $t$Qual é o primeiro mandamento?$t$, $t$O primeiro mandamento é: "Não terás outros deuses além de mim".$t$, $t$Ex 20.3.$t$),
  ($t$breve-catecismo-46$t$, $t$breve-catecismo$t$, 46, null, $t$Pergunta 46$t$, $t$Que exige o primeiro mandamento?$t$, $t$O primeiro mandamento exige de nós o conhecer e reconhecer a Deus como o único Deus verdadeiro, e nosso Deus; e como tal adorá-lo.$t$, $t$1Cr 28.9; Dt 26.17; Sl 95.6-7.$t$),
  ($t$breve-catecismo-47$t$, $t$breve-catecismo$t$, 47, null, $t$Pergunta 47$t$, $t$Que proíbe o primeiro mandamento?$t$, $t$O primeiro mandamento proíbe o negar, ou deixar de adorar ou glorificar ao verdadeiro Deus, como Deus, e nosso Deus; e dar a qualquer outro a adoração e a glória que só a Ele são devidas.$t$, $t$Sl 14.1; Rm 1.20-21, 25; Sl 8.11.$t$),
  ($t$breve-catecismo-48$t$, $t$breve-catecismo$t$, 48, null, $t$Pergunta 48$t$, $t$Que se nos ensina especialmente pelas palavras "além de mim", no primeiro mandamento?$t$, $t$As palavras "além de mim", no primeiro mandamento, ensinam-nos que Deus, que vê todas as coisas, toma conhecimento e muito se ofende do pecado de ter-se em seu lugar outro deus.$t$, $t$Sl 139.1-3; Dt 30.17-18.$t$),
  ($t$breve-catecismo-49$t$, $t$breve-catecismo$t$, 49, null, $t$Pergunta 49$t$, $t$Qual é o segundo mandamento?$t$, $t$O segundo mandamento é: "Não farás para ti imagem de escultura, nem figura alguma de tudo que há em cima no Céu, e do que há embaixo na terra, nem de coisa alguma que haja nas águas, debaixo da terra. Não as adorarás, nem lhes darás culto; porque eu sou o Senhor teu Deus, o Deus zeloso, que vinga a iniqüidade dos pais nos filhos até à terceira e quarta geração daqueles que me aborrecem; e que usa de misericórdia com milhares daqueles que me amam e que guardam os meus preceitos".$t$, $t$Ex 20.4-6.$t$),
  ($t$breve-catecismo-50$t$, $t$breve-catecismo$t$, 50, null, $t$Pergunta 50$t$, $t$Que exige o segundo mandamento?$t$, $t$O segundo mandamento exige que recebamos, observemos e guardemos puros e inteiros todo o culto e ordenanças religiosas que Deus instituiu na sua Palavra.$t$, $t$Dt 12.32; Mt 28.20; Jo 4.23-24.$t$),
  ($t$breve-catecismo-51$t$, $t$breve-catecismo$t$, 51, null, $t$Pergunta 51$t$, $t$Que proíbe o segundo mandamento?$t$, $t$O segundo mandamento proíbe o adorar a Deus por meio de imagens, ou de qualquer outra maneira não prescrita na sua Palavra.$t$, $t$Rm 1.22-23; 2Rs 18.3-4.$t$),
  ($t$breve-catecismo-52$t$, $t$breve-catecismo$t$, 52, null, $t$Pergunta 52$t$, $t$Quais são as razões anexas ao segundo mandamento?$t$, $t$As razões anexas ao segundo mandamento são a soberania de Deus sobre nós, a sua propriedade em nós em nós, e o zelo que Ele tem pelo seu culto.$t$, $t$Sl 45.11; 100.3; Ex 34.14; 1Co 10.22.$t$),
  ($t$breve-catecismo-53$t$, $t$breve-catecismo$t$, 53, null, $t$Pergunta 53$t$, $t$Qual é o terceiro mandamento?$t$, $t$O terceiro mandamento é: "Não tomarás o nome do Senhor teu Deus em vão, porque o Senhor não terá por inocente aquele que tomar em vão o nome do Senhor seu Deus".$t$, $t$Ex 20.7.$t$),
  ($t$breve-catecismo-54$t$, $t$breve-catecismo$t$, 54, null, $t$Pergunta 54$t$, $t$Que exige o terceiro mandamento?$t$, $t$O terceiro mandamento exige o santo e reverente uso dos nomes, títulos, atributos, ordenanças, palavras e obras de Deus.$t$, $t$Sl 29,2; Ap 15.3-4; Ec 5.1; Sl 138.2; 104.24.$t$),
  ($t$breve-catecismo-55$t$, $t$breve-catecismo$t$, 55, null, $t$Pergunta 55$t$, $t$O que proíbe o terceiro mandamento?$t$, $t$O terceiro mandamento proíbe toda a profanação ou abuso das coisas por meio das quais Deus se faz conhecer.$t$, $t$Lv 19.12; Mt 5.34-35.$t$),
  ($t$breve-catecismo-56$t$, $t$breve-catecismo$t$, 56, null, $t$Pergunta 56$t$, $t$Qual é a razão anexa ao terceiro mandamento?$t$, $t$A razão anexa ao terceiro mandamento é que, embora os transgressores deste mandamento escapem do castigo dos homens, o Senhor nosso Deus não os deixará escapar do seu justo juízo.$t$, $t$Dt 28.58-59.$t$),
  ($t$breve-catecismo-57$t$, $t$breve-catecismo$t$, 57, null, $t$Pergunta 57$t$, $t$Qual é o quarto mandamento?$t$, $t$O quarto mandamento é: "Lembra-te de santificar o dia do Sábado. Trabalharás seis dias, e farás nele tudo o que tens para fazer. O sétimo dia, porém, é o Sábado do Senhor teu Deus. Não farás nesse dia, obra alguma, nem tu, nem teu filho, nem tua filha, nem o teu servo, nem a tua serva, nem o teu animal, nem o peregrino que vive das tuas portas para dentro. Porque o Senhor fez em seis dias o céu, a terra e o mar, e tudo o que neles há, e descansou no sétimo dia. Por isso o Senhor abençoou o dia sétimo e o santificou".$t$, $t$Ex 20. 8.11.$t$),
  ($t$breve-catecismo-58$t$, $t$breve-catecismo$t$, 58, null, $t$Pergunta 58$t$, $t$Que exige o quarto mandamento?$t$, $t$O quarto mandamento exige que consagremos a Deus os tempos determinados em sua Palavra, particularmente um dia inteiro em cada sete, para ser um dia de santo descanso a Ele dedicado.$t$, $t$Lv 19.30; Dt 5.12.$t$),
  ($t$breve-catecismo-59$t$, $t$breve-catecismo$t$, 59, null, $t$Pergunta 59$t$, $t$Qual dos sete dias designou Deus para esse descanso semanal?$t$, $t$Desde o princípio do mundo até à ressurreição de Cristo, Deus designou o sétimo dia da semana para o descanso semanal; e desde então o primeiro dia da semana para continuar sempre até ao fim do mundo, que é o Sábado cristão, ou Domingo.$t$, $t$Gn 2.3; Ex 16.23; At 20.7; 1Co 16.1-2; Ap 1.10.$t$),
  ($t$breve-catecismo-60$t$, $t$breve-catecismo$t$, 60, null, $t$Pergunta 60$t$, $t$De que modo se deve santificar o Domingo?$t$, $t$Deve-se santificar o Domingo com um santo repouso por todo aquele dia, mesmo das ocupações e recreações temporais que são permitidas nos outros dias; empregando todo o tempo em exercícios públicos e particulares de adoração a Deus, Exceto o tempo preciso para as obras de pura necessidade e misericórdia.$t$, $t$Lv 23.3; Is 58.13-14; Mt 12.11-12; Mc 2.27-28.$t$),
  ($t$breve-catecismo-61$t$, $t$breve-catecismo$t$, 61, null, $t$Pergunta 61$t$, $t$Que proíbe o quarto mandamento?$t$, $t$O quarto mandamento proíbe a omissão ou a negligência no cumprimento dos deveres exigidos, e a profanação deste dia por meio de ociosidade ou por fazer aquilo que é em si mesmo pecaminoso, ou por desnecessários pensamentos, palavras, ou obras acerca de nossos negócios e recreações temporais.$t$, $t$Jr 17.21; Lc 23.56.$t$),
  ($t$breve-catecismo-62$t$, $t$breve-catecismo$t$, 62, null, $t$Pergunta 62$t$, $t$Quais são as razões anexas ao quarto mandamento?$t$, $t$As razões anexas ao quarto mandamento são: a permissão que Deus nos concede de fazermos uso dos seis dias da semana para os nossos interesses temporais; o reclamar ele para si a propriedade especial do dia sétimo, o seu próprio exemplo, e a benção que ele conferiu ao dia do descanso.$t$, $t$Ex 31. 15-16; Lv 23.3; Ex 31.17; Gn 2.3.$t$),
  ($t$breve-catecismo-63$t$, $t$breve-catecismo$t$, 63, null, $t$Pergunta 63$t$, $t$Qual é o quinto mandamento?$t$, $t$O quinto mandamento é: "Honrarás a teu pai e a tua mãe, para teres uma dilatada vida sobre a terra que o Senhor teu Deus te há de dar".$t$, $t$Ex 20.12.$t$),
  ($t$breve-catecismo-64$t$, $t$breve-catecismo$t$, 64, null, $t$Pergunta 64$t$, $t$Que exige o quinto mandamento?$t$, $t$O quinto mandamento exige a conservação da honra e o desempenho dos deveres pertencentes a cada um em suas diferentes condições e relações, como superiores, inferiores, ou iguais.$t$, $t$Ef 6.1-3; Rm 13.1-2; 12.10.$t$),
  ($t$breve-catecismo-65$t$, $t$breve-catecismo$t$, 65, null, $t$Pergunta 65$t$, $t$Que proíbe o quinto mandamento?$t$, $t$O quinto mandamento proíbe negligenciarmos ou fazermos alguma coisa contra a honra e dever que pertencem a cada um em suas diferentes condições e relações.$t$, $t$Rm 13.7-8.$t$),
  ($t$breve-catecismo-66$t$, $t$breve-catecismo$t$, 66, null, $t$Pergunta 66$t$, $t$Qual é a razão anexa ao quinto mandamento?$t$, $t$A razão anexa ao quinto mandamento é uma promessa de longa vida e prosperidade (quanto sirva para glória de Deus e bem do homem) a todos aqueles que guardam este mandamento.$t$, $t$Ef 6.2-3.$t$),
  ($t$breve-catecismo-67$t$, $t$breve-catecismo$t$, 67, null, $t$Pergunta 67$t$, $t$Qual é o sexto mandamento?$t$, $t$O sexto mandamento é: "Não matarás".$t$, $t$Ex 20.13.$t$),
  ($t$breve-catecismo-68$t$, $t$breve-catecismo$t$, 68, null, $t$Pergunta 68$t$, $t$Que exige o sexto mandamento?$t$, $t$O sexto mandamento exige todos os esforços lícitos para conservar a nossa vida e a dos nossos semelhantes.$t$, $t$Sl 132.3-4; At 27.33-34; Rm 12.20-21; Lc 10.33-37.$t$),
  ($t$breve-catecismo-69$t$, $t$breve-catecismo$t$, 69, null, $t$Pergunta 69$t$, $t$Que proíbe o sexto mandamento?$t$, $t$O sexto mandamento proíbe o tirar a nossa própria vida, ou a do nosso próximo injustamente, e tudo aquilo que para isso concorre.$t$, $t$At 16.28; Gn 9.6; Dt 24.6; Pv 24.11-12; 1Jo 3.15.$t$),
  ($t$breve-catecismo-70$t$, $t$breve-catecismo$t$, 70, null, $t$Pergunta 70$t$, $t$Qual é o sétimo mandamento?$t$, $t$O sétimo mandamento é: "Não adulterarás"$t$, $t$Ex 24.14.$t$),
  ($t$breve-catecismo-71$t$, $t$breve-catecismo$t$, 71, null, $t$Pergunta 71$t$, $t$Que exige o sétimo mandamento?$t$, $t$O sétimo mandamento exige a conservação da nossa própria castidade, e da do nosso próximo, no coração, nas palavras e nos costumes.$t$, $t$1Ts 4.4; Ef 4.29; 5.11-12; 1Pe 3.2.$t$),
  ($t$breve-catecismo-72$t$, $t$breve-catecismo$t$, 72, null, $t$Pergunta 72$t$, $t$Que proíbe o sétimo mandamento?$t$, $t$O sétimo mandamento proíbe todos os pensamentos, palavras e ações impuras.$t$, $t$Mt 5.28; Ef 5.3-4.$t$),
  ($t$breve-catecismo-73$t$, $t$breve-catecismo$t$, 73, null, $t$Pergunta 73$t$, $t$Qual é o oitavo mandamento?$t$, $t$O oitavo mandamento é: "Não furtarás".$t$, $t$Ex 20.15.$t$),
  ($t$breve-catecismo-74$t$, $t$breve-catecismo$t$, 74, null, $t$Pergunta 74$t$, $t$Que exige o oitavo mandamento?$t$, $t$O oitavo mandamento exige que procuremos o lícito adiantamento das riquezas e do estado exterior, tanto nosso como do nosso próximo.$t$, $t$Pv. 27.23; 22.1-14; Fl 2.4; Ex 23.4-6.$t$),
  ($t$breve-catecismo-75$t$, $t$breve-catecismo$t$, 75, null, $t$Pergunta 75$t$, $t$Que proíbe o oitavo mandamento?$t$, $t$O oitavo mandamento proíbe tudo o que impede ou pode impedir injustamente o adiantamento da riqueza ou do bem-estar, tanto nosso como do nosso próximo.$t$, $t$Pv 28.19; 1Tm 5.8; Tg 5.1-4.$t$),
  ($t$breve-catecismo-76$t$, $t$breve-catecismo$t$, 76, null, $t$Pergunta 76$t$, $t$Qual é o nono mandamento?$t$, $t$O nono mandamento é: "Não dirás falso testemunho contra o teu próximo".$t$, $t$Ex 20.16.$t$),
  ($t$breve-catecismo-77$t$, $t$breve-catecismo$t$, 77, null, $t$Pergunta 77$t$, $t$Que exige o nono mandamento?$t$, $t$O nono mandamento exige a conservação e promoção da verdade entre os homens, e a manutenção da nossa boa reputação, e a do nosso próximo, especialmente quando somos chamados a dar testemunho.$t$, $t$Ef 4.25; 1Pe 3.16; At 25.10; 3Jo 12; Pv 14.5, 25; Mt 5.37.$t$),
  ($t$breve-catecismo-78$t$, $t$breve-catecismo$t$, 78, null, $t$Pergunta 78$t$, $t$Que proíbe o nono mandamento?$t$, $t$O nono mandamento proíbe tudo o que é prejudicial à verdade, ou injurioso, tanto à nossa reputação como à do nosso próximo.$t$, $t$Cl 3.9; 2Co 8.20-21; Sl 15.3; 12.3.$t$),
  ($t$breve-catecismo-79$t$, $t$breve-catecismo$t$, 79, null, $t$Pergunta 79$t$, $t$Qual é o décimo mandamento?$t$, $t$O décimo mandamento é : "Não cobiçarás a casa do teu próximo; não desejarás a sua mulher, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma que lhe pertença.$t$, $t$Ex 20.17.$t$),
  ($t$breve-catecismo-80$t$, $t$breve-catecismo$t$, 80, null, $t$Pergunta 80$t$, $t$Que exige o décimo mandamento?$t$, $t$O décimo mandamento exige o pleno contentamento com a nossa condição, bem como disposição caridosa para com o nosso próximo e tudo o que lhe pertence.$t$, $t$Hb 13.5; 1Tm 6.6-10; Lv 19.18; 1Co 13.4-6.$t$),
  ($t$breve-catecismo-81$t$, $t$breve-catecismo$t$, 81, null, $t$Pergunta 81$t$, $t$O que proíbe o décimo mandamento?$t$, $t$O décimo mandamento proíbe todo o descontentamento com a nossa condição, todo o movimento de inveja ou pesar à vista da prosperidade do nosso próximo e todas as tendências ou afeições desordenadas a alguma coisa que lhe pertence.$t$, $t$1Co 10.10; Gl 5.26; Cl 3.5; 1Tm 6.6-10.$t$),
  ($t$breve-catecismo-82$t$, $t$breve-catecismo$t$, 82, null, $t$Pergunta 82$t$, $t$Será alguém capaz de guardar perfeitamente os mandamentos de Deus?$t$, $t$Nenhum mero homem, desde a queda de Adão, é capaz, nesta vida, de guardar perfeitamente os mandamentos de Deus, mas diariamente os quebranta por pensamentos, palavras e obras.$t$, $t$Rm 3.9-10; Tg 3.2.$t$),
  ($t$breve-catecismo-83$t$, $t$breve-catecismo$t$, 83, null, $t$Pergunta 83$t$, $t$São igualmente odiosas todas as transgressões da lei?$t$, $t$Alguns pecados em si mesmos, e em razão de circunstâncias agravantes, são mais odiosos à vista de Deus do que outros.$t$, $t$Sl 19.13; Mt 11.24; Lc 12.10; Hb 2.2-3.$t$),
  ($t$breve-catecismo-84$t$, $t$breve-catecismo$t$, 84, null, $t$Pergunta 84$t$, $t$Que merece cada pecado?$t$, $t$Cada pecado merece a ira e a maldição de Deus, tanto nesta vida como na vindoura.$t$, $t$Gl 3.10; Tg 2.10; Mt 25.41.$t$),
  ($t$breve-catecismo-85$t$, $t$breve-catecismo$t$, 85, null, $t$Pergunta 85$t$, $t$Que exige Deus de nós para que possamos escapar a sua ira e maldição em que temos incorrido pelo pecado?$t$, $t$Para escaparmos à ira e maldição de Deus, em que temos incorrido pelo pecado, Deus exige de nós fé em Jesus Cristo e arrependimento para a vida, com o uso diligente de todos os meios exteriores pelos quais Cristo nos comunica as bênçãos da redenção.$t$, $t$At 20.21; 2Pe 1.10; Hb 2.3; 1Tm 4.16.$t$),
  ($t$breve-catecismo-86$t$, $t$breve-catecismo$t$, 86, null, $t$Pergunta 86$t$, $t$Que é fé em Jesus Cristo?$t$, $t$Fé em Jesus Cristo é uma graça salvadora, pela qual o recebemos e confiamos só nEle para a salvação, como Ele nos é oferecido.$t$, $t$At 16.31; Hb 10.39; Jo 1.12; Fp 3.9; Ap 22.17.$t$),
  ($t$breve-catecismo-87$t$, $t$breve-catecismo$t$, 87, null, $t$Pergunta 87$t$, $t$Que é arrependimento para a vida?$t$, $t$Arrependimento para a vida é uma graça salvadora pela qual o pecador, tendo um verdadeiro sentimento do seu pecado e percepção da misericórdia de Deus em Cristo, se enche de tristeza e de horror pelos seus pecados, abandona-os e volta para Deus, inteiramente resolvido a prestar-lhe nova obediência.$t$, $t$2Co 7.10; At 2.37; Lc 1.77-79; Jr 31.18-19; Rm 6.18.$t$),
  ($t$breve-catecismo-88$t$, $t$breve-catecismo$t$, 88, null, $t$Pergunta 88$t$, $t$Quais são os meios exteriores e ordinários pelos quais Cristo nos comunica as bênçãos da redenção?$t$, $t$Os meios exteriores e ordinários pelos quais Cristo nos comunica as bênçãos da redenção, são as suas ordenanças, especialmente a Palavra, os sacramentos e a oração; as quais todas se tornam eficazes aos eleitos para a salvação.$t$, $t$At 2.41-42.$t$),
  ($t$breve-catecismo-89$t$, $t$breve-catecismo$t$, 89, null, $t$Pergunta 89$t$, $t$Como se torna a Palavra eficaz para a salvação?$t$, $t$O Espírito de Deus torna a leitura e especialmente a pregação da Palavra, meios eficazes para convencer e converter os pecadores, para os edificar em santidade e conforto, por meio da fé para a salvação.$t$, $t$Ne 8.8; At 20.32; Rm 15.4; 2Tm 3.15;.$t$),
  ($t$breve-catecismo-90$t$, $t$breve-catecismo$t$, 90, null, $t$Pergunta 90$t$, $t$Como se deve ler e ouvir a Palavra a fim de que ela se torne eficaz para a salvação?$t$, $t$Para que a Palavra se torne eficaz para a salvação, devemos ouvi-la com diligência, preparação e oração; recebê-la com fé e amor, guardá-la em nossos corações e praticá-la em nossas vidas.$t$, $t$Dt 6.6-7; 1Pe 2.1-2; Sl 119.11-18; Rm 1.16; 2Ts 2.10; Tg 1.21-25.$t$),
  ($t$breve-catecismo-91$t$, $t$breve-catecismo$t$, 91, null, $t$Pergunta 91$t$, $t$Como se tornam os sacramentos meios eficazes para a salvação?$t$, $t$Os sacramentos tornam-se meios eficazes para a salvação, não por alguma virtude que eles ou aqueles que os ministram tenham, mas somente pela bênção de Cristo e pela obra do seu Espírito naqueles que pela fé os recebem.$t$, $t$1Pe 3.21; Rm 2.28-29; 1Co 12.13; 10.16-17.$t$),
  ($t$breve-catecismo-92$t$, $t$breve-catecismo$t$, 92, null, $t$Pergunta 92$t$, $t$Que é um sacramento?$t$, $t$Um sacramento é uma santa ordenança, instituída por Cristo, na qual, por sinais sensíveis, Cristo e as bênçãos do novo pacto são representadas, seladas e aplicadas aos crentes.$t$, $t$Mt 26.26-28; 28.19; Rm 4.11.$t$),
  ($t$breve-catecismo-93$t$, $t$breve-catecismo$t$, 93, null, $t$Pergunta 93$t$, $t$Quais são os sacramentos do Novo Testamento?$t$, $t$Os sacramentos do Novo Testamento são o Batismo e a Ceia do Senhor.$t$, $t$At 10.47-48; 1Co 11.23-26.$t$),
  ($t$breve-catecismo-94$t$, $t$breve-catecismo$t$, 94, null, $t$Pergunta 94$t$, $t$Que é o Batismo?$t$, $t$O Batismo é o sacramento no qual o lavar com água em nome do Pai, do Filho e do Espírito Santo significa e sela a nossa união com Cristo, a participação das bênçãos do pacto da graça, e a promessa de pertencermos ao Senhor.$t$, $t$Mt 28.19; Jo 3.5; Rm 6.1-11; Gl 3.27.$t$),
  ($t$breve-catecismo-95$t$, $t$breve-catecismo$t$, 95, null, $t$Pergunta 95$t$, $t$A quem deve ser ministrado o Batismo?$t$, $t$O Batismo não deve ser ministrado àqueles que estão fora da igreja visível, enquanto não professarem sua fé em Cristo e obediência a Ele; mas os filhos daqueles que são membros da igreja visível devem ser batizados.$t$, $t$At 18.8; Gn 17.7-14; At 2.38-39; 1Co 7.14.$t$),
  ($t$breve-catecismo-96$t$, $t$breve-catecismo$t$, 96, null, $t$Pergunta 96$t$, $t$O que é a Ceia do Senhor?$t$, $t$A Ceia do Senhor é o sacramento no qual, dando-se e recebendo-se pão e vinho, conforme a instituição de Cristo, se anuncia a sua morte, e aqueles que participam dignamente tornam-se, não de uma maneira corporal e carnal, mas pela fé, participantes do seu corpo e do seu sangue, com todas as suas bênçãos para o seu alimento espiritual e crescimento em graça.$t$, $t$1Co 11.23-26; At 3.21; 1Co 10.16.$t$),
  ($t$breve-catecismo-97$t$, $t$breve-catecismo$t$, 97, null, $t$Pergunta 97$t$, $t$Que se exige para participar dignamente da Ceia do Senhor?$t$, $t$Exige-se daqueles que desejam participar dignamente da Ceia do Senhor que se examine sobre o seu conhecimento em discernir o corpo do Senhor, sobre a sua fé para se alimentarem dele, sobre o seu arrependimento, amor e nova obediência; para não suceder que, vindo indignamente, comam e bebam para si a condenação.$t$, $t$1Co 11.27; 31-32; Rm 6.17-18.$t$),
  ($t$breve-catecismo-98$t$, $t$breve-catecismo$t$, 98, null, $t$Pergunta 98$t$, $t$O que é Oração?$t$, $t$A Oração é um santo oferecimento dos nossos desejos a Deus, por coisas conformes com a sua vontade, em nome de Cristo, com a confissão dos nossos pecados, e um agradecido reconhecimento das suas misericórdias.$t$, $t$Sl 10.17; 145.19; 1Jo 5.14; 1.9; Jo 16.23-24; Fp 4.6.$t$),
  ($t$breve-catecismo-99$t$, $t$breve-catecismo$t$, 99, null, $t$Pergunta 99$t$, $t$Qual é a regra que Deus nos deu para nos dirigir em oração?$t$, $t$Toda palavra de Deus é útil para nos dirigir em oração, mas a regra especial de direção é aquela forma de oração que Cristo ensinou aos seus discípulos, e que geralmente se chama a Oração Dominical.$t$, $t$Rm 8.26; Sl 119.170; Mt 6.9-13.$t$),
  ($t$breve-catecismo-100$t$, $t$breve-catecismo$t$, 100, null, $t$Pergunta 100$t$, $t$Que nos ensina o prefácio da Oração Dominical?$t$, $t$O prefácio da Oração Dominical, que é: "Pai nosso que estás no Céu", ensina-nos que nos devemos aproximar de Deus com toda a santa reverência e confiança, como filhos a um pai poderoso e pronto para nos ajudar, e também nos ensina a orar com os outros e por eles.$t$, $t$Lc 11.13; Rm 8.15; 1Tm 2.1-2.$t$),
  ($t$breve-catecismo-101$t$, $t$breve-catecismo$t$, 101, null, $t$Pergunta 101$t$, $t$Pelo que oramos na primeira petição?$t$, $t$Na primeira petição que é: "Santificado seja o Teu nome" pedimos que Deus nos habilite a nós e aos outros a glorificá-lo em tudo aquilo em que se dá a conhecer; e que disponha tudo para sua glória.$t$, $t$Sl 67.1-3; Rm 11.36; Ap 4.11.$t$),
  ($t$breve-catecismo-102$t$, $t$breve-catecismo$t$, 102, null, $t$Pergunta 102$t$, $t$Pelo que oramos na segunda petição?$t$, $t$Na segunda petição, que é: "Venha o Teu reino", pedimos que o reino de Satanás seja destruído e que o reino da graça seja adiantado; que nós e os outros a ele sejamos guiados e nele guardados, e que cedo venha o reino da glória.$t$, $t$Sl 68.1; Jo 12.31; Mt 9.37-38; 2Ts 3.1; Rm 10.1; Ap 22.20.$t$),
  ($t$breve-catecismo-103$t$, $t$breve-catecismo$t$, 103, null, $t$Pergunta 103$t$, $t$Pelo que oramos na terceira petição?$t$, $t$Na terceira petição, que é: "Seja feita Tua vontade, assim na terra como no Céu", pedimos que Deus, pela sua graça, nos torne capazes e desejosos de conhecer a sua vontade, de obedecer e submeter-nos a ela em tudo, como fazem os anjos no Céu.$t$, $t$Mt 24.39; Fp 1.9-11; Sl 103.20-21.$t$),
  ($t$breve-catecismo-104$t$, $t$breve-catecismo$t$, 104, null, $t$Pergunta 104$t$, $t$Pelo que oramos na quarta petição?$t$, $t$Na quarta petição, que é: O pão nosso de cada dia nos dá hoje", pedimos que da livre dádiva de Deus recebamos uma porção suficiente das coisas boas desta vida, e gozemos com elas de suas bênçãos.$t$, $t$Pv 30.8-9; 1Tm 6.6-8; Pv 10.22.$t$),
  ($t$breve-catecismo-105$t$, $t$breve-catecismo$t$, 105, null, $t$Pergunta 105$t$, $t$Pelo que oramos na quinta petição?$t$, $t$Na quinta petição, que é: "E perdoa-nos as nossas dividas, assim como nós também perdoamos aos nossos devedores", pedimos que Deus, por amor de Cristo, nos perdoe gratuitamente os nossos pecados, o que somos animados a pedir, porque, pela Sua graça somos habilitados a perdoar de coração ao nosso próximo.$t$, $t$Sl 51.1-2, 7; Mt 18.35.$t$),
  ($t$breve-catecismo-106$t$, $t$breve-catecismo$t$, 106, null, $t$Pergunta 106$t$, $t$Pelo que oramos na sexta petição?$t$, $t$Na sexta petição, que é: "E não nos deixes cair em tentação", pedimos que Deus nos guarde de sermos tentados a pecar, ou nos preserve e livre, quando formos tentados.$t$, $t$Mt 26.41; Sl 19.13; Jo 17.15; 1Co 10.13.$t$),
  ($t$breve-catecismo-107$t$, $t$breve-catecismo$t$, 107, null, $t$Pergunta 107$t$, $t$Que nos ensina a conclusão da Oração Dominical?$t$, $t$A conclusão da Oração Dominical, que é: "Porque Teu é o reino, o poder e a glória, para sempre. Amém", ensina-nos que na Oração devemos confiar somente em Deus, e louvá-lO em nossas orações, atribuindo-Lhe reino, poder e glória. E em testemunho do nosso desejo e certeza de sermos ouvidos, dizemos: Amém.$t$, $t$Dn 9.18-19; Fp 4.6; 1Cr 29.11-13; 1Co 14.16; Ap 22.20-21.$t$);

insert into public.confissoes_itens (id, documento_id, ordem, secao, rotulo, pergunta, texto, referencias) values
  ($t$confissao-fe-1$t$, $t$confissao-fe$t$, 1, $t$Capítulo I — Da Escritura Sagrada$t$, $t$Capítulo I, seção I$t$, null, $t$Ainda que a luz da natureza e as obras da criação e da providência de tal modo manifestem a bondade, a sabedoria e o poder de Deus, que os homens ficam inescusáveis, contudo não são suficientes para dar aquele conhecimento de Deus e da sua vontade necessário para a salvação; por isso foi o Senhor servido, em diversos tempos e diferentes modos, revelar-se e declarar à sua Igreja aquela sua vontade; e depois, para melhor preservação e propagação da verdade, para o mais seguro estabelecimento e conforto da Igreja contra a corrupção da carne e malícia de Satanás e do mundo, foi igualmente servido fazê-la escrever toda. Isto torna indispensável a Escritura Sagrada, tendo cessado aqueles antigos modos de revelar Deus a sua vontade ao seu povo.$t$, $t$Sal. 19: 1-4; Rom. 1: 32, e 2: 1, e 1: 19-20, e 2: 14-15; I Cor. 1:21, e 2:13-14; Heb. 1:1-2; Luc. 1:3-4; Rom. 15:4; Mat. 4:4, 7, 10; Isa. 8: 20; I Tim. 3: 15; II Pedro 1: 19.$t$),
  ($t$confissao-fe-2$t$, $t$confissao-fe$t$, 2, $t$Capítulo I — Da Escritura Sagrada$t$, $t$Capítulo I, seção II$t$, null, $t$Sob o nome de Escritura Sagrada, ou Palavra de Deus escrita, incluem-se agora todos os livros do Velho e do Novo Testamento, que são os seguintes, todos dados por inspiração de Deus para serem a regra de fé e de prática:
O VELHO TESTAMENTO
